<?php
namespace App\Http\Controllers; use App\Models\{LibraryFine,LibraryTransaction}; use App\Policies\LibraryReportPolicy; use Illuminate\Http\Request; class LibraryReportController extends Controller {public function index(Request $r){$this->authorize('viewAny',LibraryReportPolicy::class);$q=LibraryTransaction::with(['bookCopy.book','libraryMember'])->orderByDesc('issued_on')->orderByDesc('id');if($r->filled('status'))$q->where('status',$r->status);if($r->filled('from'))$q->whereDate('issued_on','>=',$r->from);if($r->filled('to'))$q->whereDate('issued_on','<=',$r->to);return view('library_reports.index',['transactions'=>$q->paginate(25)->withQueryString(),'fines'=>LibraryFine::selectRaw('status, count(*) as total, sum(assessed_amount) as amount, sum(assessed_amount-paid_amount) as outstanding')->groupBy('status')->get()]);}}
